from collections import defaultdict
def f(I):
    H=len(I);W=len(I[0])
    pts=[(i,j) for i in range(H) for j in range(W) if I[i][j]==2]
    byrow=defaultdict(list)
    for i,j in pts: byrow[i].append(j)
    # backbone: row with exactly two 2s whose col gap is largest
    best=None
    for r,js in byrow.items():
        if len(js)==2:
            d=abs(js[1]-js[0])
            if best is None or d>best[0]: best=(d,r)
    bestd,bestrow=best
    minc=min(byrow[bestrow]); maxc=max(byrow[bestrow])
    out=[r[:] for r in I]
    for c in range(minc,maxc+1):
        out[bestrow][c]=3
    for i,j in pts:
        if i==bestrow: continue
        step=1 if i<bestrow else -1
        r=i+step
        while r!=bestrow:
            out[r][j]=3; r+=step
    return out
